import{_ as a,o,c as s,ae as t}from"./chunks/framework.Dn7Y7LSn.js";const h=JSON.parse('{"title":"Database Design & Architecture (Live Class 1 & 2)","description":"","frontmatter":{},"headers":[],"relativePath":"module-4/database-design.md","filePath":"module-4/database-design.md"}'),i={name:"module-4/database-design.md"};function r(l,e,n,d,c,g){return o(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="database-design-architecture-live-class-1-2" tabindex="-1">Database Design &amp; Architecture (Live Class 1 &amp; 2) <a class="header-anchor" href="#database-design-architecture-live-class-1-2" aria-label="Permalink to &quot;Database Design &amp; Architecture (Live Class 1 &amp; 2)&quot;">​</a></h1><h2 id="why-do-we-need-a-database" tabindex="-1">Why Do We Need a Database? <a class="header-anchor" href="#why-do-we-need-a-database" aria-label="Permalink to &quot;Why Do We Need a Database?&quot;">​</a></h2><p><strong>Code vs Data:</strong> কোড হলো ইনস্ট্রাকশন সেট, যা এক্সিকিউট করতে যে ইনফরমেশন লাগে সেটাই হলো ডাটা (Data)। কোড বা অ্যাপ্লিকেশন সাধারণত <strong>Application Server</strong>-এ রান হয়, আর ডেটা স্টোর করা হয় <strong>Database Server</strong>-এ। অ্যাপ্লিকেশন সার্ভার হতে হবে স্টেটলেস (Stateless)। ইউজারের সেশন লজিক বা কারেন্ট স্টেট সংরক্ষণের জন্য ডেটাবেজ দরকার। অ্যাপ সার্ভার ও ডেটাবেজ সার্ভার আলাদা হলে মাঝখানে নেটওয়ার্ক কমিউনিকেশন হয়, তাই কিছুটা Network Delay বা ল্যাটেন্সি থাকে।</p><h2 id="how-database-store-data" tabindex="-1">How Database Store Data? <a class="header-anchor" href="#how-database-store-data" aria-label="Permalink to &quot;How Database Store Data?&quot;">​</a></h2><p>সিস্টেম ডেটা সাধারণত RAM (মেমোরি) বা HDD/SSD (ডিস্ক)-এ রাখে।</p><ul><li><strong>MySQL, PostgreSQL:</strong> ডেটা সাধারণত ডিস্কে রাখে এবং ফার্স্ট রেসপন্সের জন্য কিছু ইনডেক্স মেমোরিতে রাখে।</li><li><strong>Redis, Memcached:</strong> পুরো ডেটা RAM-এ রাখে, যা অতি দ্রুত ফলাফল দেয়।</li></ul><h2 id="types-of-databases" tabindex="-1">Types of Databases <a class="header-anchor" href="#types-of-databases" aria-label="Permalink to &quot;Types of Databases&quot;">​</a></h2><ol><li><strong>Relational:</strong> <code>PostgreSQL</code>, <code>MySQL</code>, <code>MariaDB</code>, <code>Oracle</code> - এরা টেবিল, রো (Row) এবং কলাম আকারে ডেটা রাখে।</li><li><strong>Key-Value:</strong> <code>Redis</code>, <code>DynamoDB</code> - এরা <code>key: value</code> পেয়ারে বা ডিকশনারি আকারে ডেটা রাখে।</li><li><strong>Columnar:</strong> <code>HBase</code>, <code>Cassandra</code> - বিগ ডেটা প্রোসেসিংয়ে কলাম ওরিয়েন্টেড স্টোরেজ।</li><li><strong>Document:</strong> <code>MongoDB</code>, <code>CouchDB</code>, <code>ElasticSearch</code> - এরা JSON বা BSON ডকুমেন্ট আকারে ডেটা রাখে।</li><li><strong>Graph:</strong> <code>Neo4j</code> - বিভিন্ন নোডের মধ্যে গ্রাফ বা সম্পর্কের মাধ্যমে কানেক্ট করে।</li><li><strong>Embedded:</strong> <code>SQLite</code> - সি (C) ল্যাঙ্গুয়েজ দিয়ে তৈরি এবং অ্যাপ্লিকেশনের ভেতরে ফাইলের মধ্যে ডেটা রাখে।</li><li><strong>Time series &amp; Vector DB:</strong> লগসের জন্য টাইম-সিরিজ, এবং এআই (AI) মডেলের জন্য ভেক্টর ডেটাবেজ ব্যবহৃত হয়।</li></ol><h2 id="database-vs-schema-vs-table" tabindex="-1">Database vs Schema vs Table <a class="header-anchor" href="#database-vs-schema-vs-table" aria-label="Permalink to &quot;Database vs Schema vs Table&quot;">​</a></h2><ul><li><strong>Database:</strong> ডেটাবেজ হলো একটা বিল্ডিং (পুরো সিস্টেম)।</li><li><strong>Schema:</strong> স্কিমা হলো একটি ফ্লোর (MySQL-এ DB ও স্কিমা একই, কিন্তু PostgreSQL-এ একটি ডেটাবেজের ভেতর মাল্টিপল স্কিমা থাকে)। বিশেষ করে SaaS মাল্টি-টেন্যান্ট (Multi-tenant) অ্যাপ্লিকেশনে ভিন্ন ভিন্ন কাস্টমারের জন্য ভিন্ন স্কিমা থাকতে পারে।</li><li><strong>Table:</strong> টেবিল হলো একেকটি রুম বা সবচেয়ে ছোট ইউনিট।</li></ul><p>Production Database-এ সব প্রিভিলেজ (All Privileges/Drop) না দিয়ে শুধুমাত্র <code>Read Only</code> বা স্পেসিফিক অ্যাক্সেস দেওয়াই হলো বেস্ট প্র্যাকটিস।</p><hr><h2 id="database-schema-design-lms-example" tabindex="-1">Database Schema Design (LMS Example) <a class="header-anchor" href="#database-schema-design-lms-example" aria-label="Permalink to &quot;Database Schema Design (LMS Example)&quot;">​</a></h2><p>সিস্টেমের ডেটাবেজ ডিজাইন করার সাধারণ ধাপসমূহ:</p><ol><li><strong>Understand Business Needs:</strong> রিকয়ারমেন্ট বোঝা।</li><li><strong>Identify Entities/Tables:</strong> কী কী অবজেক্ট থাকবে (Customer, Product, Order, Employee)।</li><li><strong>Define Properties:</strong> তাদের ফিল্ড ও টাইপ (INT, VARCHAR, DATE) নির্ধারণ করা।</li><li><strong>Define Relationships:</strong> টেবিলগুলোর মধ্যকার সম্পর্ক তৈরি করা।</li></ol><h3 id="primary-key-vs-foreign-key" tabindex="-1">Primary Key vs Foreign Key <a class="header-anchor" href="#primary-key-vs-foreign-key" aria-label="Permalink to &quot;Primary Key vs Foreign Key&quot;">​</a></h3><ul><li><strong>Primary Key:</strong> টেবিলের প্রতিটি রো-কে ইউনিকলি ഐഡেন্ify করে (যেমন- <code>employee_id</code>)।</li><li><strong>Foreign Key:</strong> একটি টেবিলের প্রাইমারি কি যখন রেফারেন্স হিসেবে অন্য টেবিলে রাখা হয়, তখন তাকে ফরেন কি বলে (যেমন- অর্ডারে থাকা <code>customer_id</code>)।</li></ul><h3 id="relationship-types" tabindex="-1">Relationship Types <a class="header-anchor" href="#relationship-types" aria-label="Permalink to &quot;Relationship Types&quot;">​</a></h3><ul><li><strong>One-to-One:</strong> নির্দিষ্ট ইনটেল ডেটা আলাদা রাখতে (যেমন- User এবং UserDetails)।</li><li><strong>One-to-Many:</strong> একজন ইউজারের মাল্টিপল অর্ডার থাকতে পারে, তাই Order টেবিলে <code>user_id</code> রাখা।</li><li><strong>Many-to-Many:</strong> একাধিক কোর্সে একাধিক ট্যাগ থাকতে পারে, তাই একটি পিভট (Pivot) ইন্টারমিডিয়েট টেবিল <code>course_tags(course_id, tag_id)</code> তৈরি করতে হয়।</li></ul><h3 id="e-learning-lms-system-table-analysis-live-class" tabindex="-1">E-Learning (LMS) System Table Analysis (Live Class) <a class="header-anchor" href="#e-learning-lms-system-table-analysis-live-class" aria-label="Permalink to &quot;E-Learning (LMS) System Table Analysis (Live Class)&quot;">​</a></h3><p>একটি LMS (Learning Management System) বা EdTech সিস্টেমের জন্য ডেটাবেস টেবিলসমূহ কেমন হতে পারে:</p><ul><li><strong>users:</strong> <code>id</code>, <code>first_name</code>, <code>last_name</code>, <code>email</code>, <code>password</code>, <code>role</code> (Admin/Instructor/Student)।</li><li><strong>courses:</strong> <code>id</code>, <code>title</code>, <code>description</code>, <code>price</code>, <code>discount</code>, <code>featured_image</code>, <code>total_enrolled</code> (Normalization রুল ব্রেক হলেও পারফর্ম্যান্সের জন্য)। <em>(এখানে কোয়ারির জন্য ইনডেক্সিং এবং <code>slug</code> করা জরুরি।)</em></li><li><strong>enrollments:</strong> স্টুডেন্টদের কোর্স এনরোলমেন্টের অবস্থা (<code>status</code> ENUM না রেখে VARCHAR রাখা ভালো)।</li><li><strong>invoices &amp; invoice_items:</strong> একটি ইনভয়েসে অনেকগুলো কোর্স থাকতে পারে। কোর্সের প্রাইস পরে বদলে যেতে পারে তাই ইনভয়েস টেবিলে হিস্টোরিকাল ডাটা রাখা হয়।</li><li><strong>chapters, lessons, completed_lessons:</strong> স্টুডেন্টের প্রোগ্রেস ট্র্যাকিং।</li><li><strong>coupons, reviews:</strong> কোর্স এবং ইউজারের অ্যাসাইনকৃত ডেটা।</li></ul><h3 id="database-migration-optimization" tabindex="-1">Database Migration &amp; Optimization <a class="header-anchor" href="#database-migration-optimization" aria-label="Permalink to &quot;Database Migration &amp; Optimization&quot;">​</a></h3><p><strong>Low / No Downtime Migration:</strong> যদি আমরা <code>completed_lessons</code> থেকে মার্কসের ঘরগুলো নিয়ে একটি নতুন <code>assessments</code> টেবিল বানাতে চাই, তবে মাইগ্রেশনের ধাপগুলো হবে:</p><ol><li>নতুন <code>assessments</code> স্কিমা তৈরি করা।</li><li>পুরানো ডেটা নতুন টেবিলে সিঙ্ক বা ট্রান্সফার করা।</li><li><strong>Double Write Policy:</strong> একইসাথে অ্যাপ্লিকেশনে উভয় টেবিলেই লিখা, যেন ডেটা মিসম্যাচ না হয়।</li><li>নতুন লজিক অনুযায়ী অ্যাপ্লিকেশন আপডেট করে শুধুমাত্র নতুন টেবিল থেকে রিড করা।</li><li>পুরানো টেবিলের কলামগুলো রিমুভ (Cleanup) করা।</li></ol><p><strong>Soft Delete vs Hard Delete:</strong></p><ul><li><strong>Soft Delete:</strong> <code>deleted_at</code> কলামে টাইমস্ট্যাম্প রাখি, কিন্তু ডেটা ফিজিক্যালি ডিলিট হয় গঠন।</li><li><strong>Hard Delete:</strong> ডেটা চিরকালের জন্য মুছে ফেলা (<code>ON DELETE CASCADE</code> বা <code>ON DELETE NULL</code>)। ইউরোপীয়ান GDPR রুলসে ইউজার বললে অবশ্যই হার্ড ডিলিট করতে হয়।</li><li><strong>Pruning / Analytics DB:</strong> সফট ডিলিট করা ডেটা ২/৩ মাস পর প্রুনিং (হার্ড ডিলিট) করে দেওয়া যায়, অথবা অ্যানালিটিক্সের জন্য অন্য কোনো ডেটাবেজে ব্যাকআপ করে রাখা হয়।</li></ul>',27)])])}const p=a(i,[["render",r]]);export{h as __pageData,p as default};
